import { Controller, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxyFactory, MessagePattern, MicroserviceOptions, Payload, Transport } from "@nestjs/microservices"
import { firstValueFrom } from "rxjs"

@Controller()
class MathController {
    @MessagePattern({ cmd: "sum" }) sum(@Payload() numbers: number[]) { return numbers.reduce((a, b) => a + b, 0) }
}
@Module({ controllers: [MathController] }) class MathModule {}

async function main() {
    const ms = await NestFactory.createMicroservice<MicroserviceOptions>(MathModule, {
        transport: Transport.TCP, options: { host: "127.0.0.1", port: 4510 }, logger: false,
    })
    await ms.listen()
    console.log("Mikroservis 4510-portda tinglayapti")

    const client = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4510 } })
    console.log("sum([1..5]) =", await firstValueFrom(client.send({ cmd: "sum" }, [1, 2, 3, 4, 5])))
    await client.close()
    await ms.close()
}
main()

import { Controller, Get, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxyFactory, MessagePattern, Transport } from "@nestjs/microservices"
import { firstValueFrom } from "rxjs"

@Controller()
class AppController {
    @Get("health") health() { return { http: "ok" } }
    @MessagePattern("health") rpcHealth() { return { tcp: "ok" } }
}
@Module({ controllers: [AppController] }) class AppModule {}

async function main() {
    const app = await NestFactory.create(AppModule, { logger: false })
    app.connectMicroservice({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4511 } })
    await app.startAllMicroservices()
    await app.listen(0, "127.0.0.1")

    console.log("HTTP:", await (await fetch((await app.getUrl()) + "/health")).json())
    const client = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4511 } })
    console.log("TCP:", await firstValueFrom(client.send("health", {})))
    await client.close()
    await app.close()
}
main()

import { Controller, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxyFactory, MessagePattern, MicroserviceOptions, RpcException, Transport } from "@nestjs/microservices"
import { firstValueFrom } from "rxjs"

@Controller()
class UsersController {
    @MessagePattern("user.get")
    get(id: number) {
        if (id !== 1) throw new RpcException({ status: 404, message: `Foydalanuvchi #${id} topilmadi` })
        return { id, name: "Ali" }
    }
}
@Module({ controllers: [UsersController] }) class UsersModule {}

async function main() {
    const ms = await NestFactory.createMicroservice<MicroserviceOptions>(UsersModule, { transport: Transport.TCP, options: { host: "127.0.0.1", port: 4512 }, logger: false })
    await ms.listen()
    const client = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4512 } })
    console.log(await firstValueFrom(client.send("user.get", 1)))
    try {
        await firstValueFrom(client.send("user.get", 9))
    } catch (e) {
        console.log("xato:", e)
    }
    await client.close()
    await ms.close()
}
main()

import { Controller, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxyFactory, MessagePattern, MicroserviceOptions, Transport } from "@nestjs/microservices"
import { firstValueFrom, from, lastValueFrom, toArray } from "rxjs"

@Controller()
class ReportsController {
    @MessagePattern("report.async") async build() {
        await new Promise(r => setTimeout(r, 30))
        return { ready: true }
    }
    // Observable — bir nechta qiymat oqim sifatida yuboriladi
    @MessagePattern("report.stream") stream() { return from(["1-qism", "2-qism", "3-qism"]) }
}
@Module({ controllers: [ReportsController] }) class ReportsModule {}

async function main() {
    const ms = await NestFactory.createMicroservice<MicroserviceOptions>(ReportsModule, { transport: Transport.TCP, options: { host: "127.0.0.1", port: 4513 }, logger: false })
    await ms.listen()
    const client = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4513 } })
    console.log("async:", await firstValueFrom(client.send("report.async", {})))
    console.log("stream:", await lastValueFrom(client.send("report.stream", {}).pipe(toArray())))
    await client.close()
    await ms.close()
}
main()

