import { Controller, Get, Inject, Module, Param, ParseIntPipe } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxy, ClientsModule, MessagePattern, MicroserviceOptions, Payload, Transport } from "@nestjs/microservices"

// --- billing-service (alohida jarayon bo'lishi mumkin) ---
@Controller()
class BillingController {
    @MessagePattern("invoice.total") total(@Payload() orderId: number) { return { orderId, total: orderId * 10000 } }
}
@Module({ controllers: [BillingController] }) class BillingModule {}

// --- api-gateway ---
@Controller("orders")
class GatewayController {
    constructor(@Inject("BILLING") private readonly billing: ClientProxy) {}
    @Get(":id/total") total(@Param("id", ParseIntPipe) id: number) { return this.billing.send("invoice.total", id) }
}
@Module({
    imports: [ClientsModule.register([{ name: "BILLING", transport: Transport.TCP, options: { host: "127.0.0.1", port: 4601 } }])],
    controllers: [GatewayController],
})
class GatewayModule {}

async function main() {
    const billing = await NestFactory.createMicroservice<MicroserviceOptions>(BillingModule, { transport: Transport.TCP, options: { host: "127.0.0.1", port: 4601 }, logger: false })
    await billing.listen()
    const http = await testApp(GatewayModule)
    await http.get("/orders/7/total")
    await http.close()
    await billing.close()
}
main()

