import { Controller, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxyFactory, MessagePattern, MicroserviceOptions, Payload, Transport } from "@nestjs/microservices"
import { firstValueFrom } from "rxjs"

// libs/contracts/orders.ts — ikkala servis ham shu fayldan import qiladi
export const ORDERS_PATTERNS = { create: "orders.create", findOne: "orders.findOne" } as const
export interface OrderDto { id: number; items: string[] }

@Controller()
class OrdersController {
    private orders: OrderDto[] = []
    @MessagePattern(ORDERS_PATTERNS.create) create(@Payload() items: string[]): OrderDto {
        const order = { id: this.orders.length + 1, items }
        this.orders.push(order)
        return order
    }
    @MessagePattern(ORDERS_PATTERNS.findOne) findOne(@Payload() id: number) { return this.orders.find(o => o.id === id) ?? null }
}
@Module({ controllers: [OrdersController] }) class OrdersModule {}

async function main() {
    const ms = await NestFactory.createMicroservice<MicroserviceOptions>(OrdersModule, { transport: Transport.TCP, options: { host: "127.0.0.1", port: 4609 }, logger: false })
    await ms.listen()
    const client = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4609 } })
    const created = await firstValueFrom(client.send<OrderDto>(ORDERS_PATTERNS.create, ["choy", "non"]))
    console.log("yaratildi:", created)
    console.log("topildi:", await firstValueFrom(client.send<OrderDto | null>(ORDERS_PATTERNS.findOne, created.id)))
    await client.close(); await ms.close()
}
main()

import { ArgumentsHost, Catch, Controller, Module, RpcExceptionFilter } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxyFactory, MessagePattern, MicroserviceOptions, Transport } from "@nestjs/microservices"
import { firstValueFrom, Observable, throwError } from "rxjs"

@Catch()
class AllRpcErrors implements RpcExceptionFilter<Error> {
    catch(e: Error, _host: ArgumentsHost): Observable<never> {
        return throwError(() => ({ ok: false, error: e.message, type: e.constructor.name }))
    }
}

@Controller()
class DemoController { @MessagePattern("crash") crash() { throw new TypeError("kutilmagan null") } }
@Module({ controllers: [DemoController] }) class DemoModule {}

async function main() {
    const ms = await NestFactory.createMicroservice<MicroserviceOptions>(DemoModule, { transport: Transport.TCP, options: { host: "127.0.0.1", port: 4610 }, logger: false })
    ms.useGlobalFilters(new AllRpcErrors())
    await ms.listen()
    const client = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4610 } })
    try { await firstValueFrom(client.send("crash", {})) } catch (e) { console.log(e) }
    await client.close(); await ms.close()
}
main()

import { Controller, Inject, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxy, ClientProxyFactory, ClientsModule, MessagePattern, MicroserviceOptions, Payload, Transport } from "@nestjs/microservices"
import { firstValueFrom } from "rxjs"

@Controller()
class InventoryController {
    private stock: Record<string, number> = { choy: 3 }
    @MessagePattern("stock.reserve") reserve(@Payload() sku: string) {
        if (!this.stock[sku]) return { ok: false }
        this.stock[sku]--
        return { ok: true, left: this.stock[sku] }
    }
}
@Module({ controllers: [InventoryController] }) class InventoryModule {}

@Controller()
class OrdersController {
    constructor(@Inject("INVENTORY") private readonly inventory: ClientProxy) {}
    @MessagePattern("order.place") async place(@Payload() sku: string) {
        const r = await firstValueFrom(this.inventory.send("stock.reserve", sku))
        return r.ok ? { status: "tasdiqlandi", left: r.left } : { status: "rad etildi: omborda yo'q" }
    }
}
@Module({
    imports: [ClientsModule.register([{ name: "INVENTORY", transport: Transport.TCP, options: { host: "127.0.0.1", port: 4611 } }])],
    controllers: [OrdersController],
})
class OrdersModule {}

async function main() {
    const inv = await NestFactory.createMicroservice<MicroserviceOptions>(InventoryModule, { transport: Transport.TCP, options: { host: "127.0.0.1", port: 4611 }, logger: false })
    const ord = await NestFactory.createMicroservice<MicroserviceOptions>(OrdersModule, { transport: Transport.TCP, options: { host: "127.0.0.1", port: 4612 }, logger: false })
    await inv.listen(); await ord.listen()
    const gateway = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4612 } })
    for (const sku of ["choy", "kofe"]) console.log(sku, "→", await firstValueFrom(gateway.send("order.place", sku)))
    await gateway.close(); await ord.close(); await inv.close()
}
main()

