import { Controller, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxyFactory, MessagePattern, MicroserviceOptions, Transport } from "@nestjs/microservices"
import { firstValueFrom } from "rxjs"

let active = 0, peak = 0
const queue: (() => void)[] = []
const acquire = () => new Promise<void>(r => { if (active < 2) { active++; r() } else queue.push(() => { active++; r() }) })
const release = () => { active--; queue.shift()?.() }
@Controller() class Reports {
    @MessagePattern("report.build") async build(id: number) { await acquire(); peak = Math.max(peak, active); await new Promise(r => setTimeout(r, 20)); release(); return `hisobot-${id}` }
}
