import { Controller, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { CustomTransportStrategy, MessagePattern, Server } from "@nestjs/microservices"
import { EventEmitter } from "node:events"

const bus = new EventEmitter()
class InMemoryServer extends Server implements CustomTransportStrategy {
    listen(cb: () => void) {
        bus.on("request", async (pattern: string, data: unknown, reply: (r: unknown) => void) => {
            const handler = this.getHandlerByPattern(pattern)
            if (!handler) return reply({ error: `handler yo'q: ${pattern}` })
            const result = await handler(data)
            reply(await new Promise(r => this.transformToObservable(result).subscribe(r)))
        })
        cb()
    }
    close() { bus.removeAllListeners() }
    on() { throw new Error("qo'llab-quvvatlanmaydi") }
    unwrap<T>(): T { return bus as T }
}
@Controller() class Math { @MessagePattern("sum") sum(nums: number[]) { return nums.reduce((a, b) => a + b, 0) } }
@Module({ controllers: [Math] }) class AppModule {}
const request = (pattern: string, data: unknown) => new Promise(r => bus.emit("request", pattern, data, r))

async function main() {
    const ms = await NestFactory.createMicroservice(AppModule, { strategy: new InMemoryServer(), logger: false })
    await ms.listen()
    console.log("sum:", await request("sum", [1, 2, 3, 4]))
    console.log("noma'lum:", await request("mul", [2, 3]))
    await ms.close()
}
main()

