import { CACHE_MANAGER, CacheModule } from "@nestjs/cache-manager"
import { ClientProxyFactory, MessagePattern, MicroserviceOptions, Transport } from "@nestjs/microservices"
import type { Cache } from "cache-manager"
import { firstValueFrom } from "rxjs"

let dbHits = 0
@Controller() class Rates {
    constructor(@Inject(CACHE_MANAGER) private cache: Cache) {}
    @MessagePattern("rate") rate(cur: string) { return this.cache.wrap(`rate:${cur}`, async () => { dbHits++; return cur === "USD" ? 12650 : 13700 }) }
}
@Module({ imports: [CacheModule.register()], controllers: [Rates] }) class AppModule {}

async function main() {
    const ms = await NestFactory.createMicroservice<MicroserviceOptions>(AppModule, { transport: Transport.TCP, options: { host: "127.0.0.1", port: 4822 }, logger: false })
    await ms.listen()
    const c = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4822 } })
    for (const cur of ["USD", "USD", "EUR", "USD"]) await firstValueFrom(c.send("rate", cur))
    console.log("4 so'rov, bazaga murojaat:", dbHits)
    await c.close(); await ms.close()
}
main()

import { Controller, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxyFactory, MessagePattern, MicroserviceOptions, Transport } from "@nestjs/microservices"
import { firstValueFrom } from "rxjs"

let generation = 0
@Controller() class C { @MessagePattern("gen") g() { return generation } }
@Module({ controllers: [C] }) class AppModule {}
const start = async () => { generation++; const ms = await NestFactory.createMicroservice<MicroserviceOptions>(AppModule, { transport: Transport.TCP, options: { host: "127.0.0.1", port: 4823 }, logger: false }); await ms.listen(); return ms }

async function main() {
    let ms = await start()
    const c = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4823 } })
    console.log("1-server:", await firstValueFrom(c.send("gen", {})))
    await ms.close()
    ms = await start()
    try { console.log("qayta ishga tushgach:", await firstValueFrom(c.send("gen", {}))) } catch (e) { console.log("eski ulanish:", (e as Error).message) }
    await c.close()
    const fresh = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4823 } })
    console.log("yangi mijoz:", await firstValueFrom(fresh.send("gen", {})))
    await fresh.close(); await ms.close()
}
main()

