import { Controller, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxyFactory, MessagePattern, MicroserviceOptions, RpcException, Transport } from "@nestjs/microservices"
import { firstValueFrom } from "rxjs"

const NOW = 1_700_000_000_000
@Controller() class C { @MessagePattern("report") r(p: { deadline: number }) { if (p.deadline < NOW) throw new RpcException("Muddat o'tgan — natija endi kerak emas"); return "hisobot tayyor" } }
@Module({ controllers: [C] }) class AppModule {}

async function main() {
    const ms = await NestFactory.createMicroservice<MicroserviceOptions>(AppModule, { transport: Transport.TCP, options: { host: "127.0.0.1", port: 4827 }, logger: false })
    await ms.listen()
    const c = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4827 } })
    console.log(await firstValueFrom(c.send("report", { deadline: NOW + 5000 })))
    try { await firstValueFrom(c.send("report", { deadline: NOW - 1 })) } catch (e) { console.log("xato:", e) }
    await c.close(); await ms.close()
}
main()

import { Controller, Module, ValidationPipe } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxyFactory, MessagePattern, Payload, RpcException, Transport } from "@nestjs/microservices"
import { IsInt, Min } from "class-validator"
import { firstValueFrom } from "rxjs"

class ReserveDto { @IsInt() @Min(1) qty!: number }

@Controller()
class StockController {
    @MessagePattern("reserve")
    reserve(@Payload() dto: ReserveDto) { return { reserved: dto.qty } }
}

@Module({ controllers: [StockController] })
class AppModule {}

async function run(inheritAppConfig: boolean, port: number) {
    const app = await NestFactory.create(AppModule, { logger: false })
    app.useGlobalPipes(new ValidationPipe({ exceptionFactory: () => new RpcException("qty noto'g'ri") }))
    app.connectMicroservice({ transport: Transport.TCP, options: { host: "127.0.0.1", port } }, { inheritAppConfig })
    await app.startAllMicroservices()
    await app.listen(0, "127.0.0.1")

    const client = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port } })
    try {
        console.log(`inheritAppConfig=${inheritAppConfig}:`, await firstValueFrom(client.send("reserve", { qty: 0 })))
    } catch (error) {
        console.log(`inheritAppConfig=${inheritAppConfig}: rad etildi`, error)
    }
    await client.close()
    await app.close()
}

async function main() {
    await run(false, 4933)      // pipe mikroservisga yetmaydi — qty: 0 o'tib ketadi
    await run(true, 4934)       // pipe meros qilindi — qty: 0 rad etiladi
}
main()

