    await app.listen()

    const client = ClientProxyFactory.create({ transport: Transport.RMQ, options: rmq })
    await client.connect()
    client.emit("order.created", { id: 7 }).subscribe()
    await new Promise(resolve => setTimeout(resolve, 200))
    await client.close()
    await app.close()
