import { CallHandler, Controller, ExecutionContext, Injectable, Module, NestInterceptor, UseInterceptors } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxyFactory, MessagePattern, MicroserviceOptions, Transport } from "@nestjs/microservices"
import { firstValueFrom, of, tap } from "rxjs"

const store = new Map<string, unknown>()
@Injectable() class RpcCache implements NestInterceptor {
    intercept(ctx: ExecutionContext, next: CallHandler) {
        const key = `${ctx.switchToRpc().getContext().getPattern()}:${JSON.stringify(ctx.switchToRpc().getData())}`
        return store.has(key) ? of(store.get(key)) : next.handle().pipe(tap(v => store.set(key, v)))
    }
}
let computed = 0
@Controller() @UseInterceptors(RpcCache) class C { @MessagePattern("fib") fib(n: number) { computed++; let [a, b] = [0, 1]; for (let i = 0; i < n; i++) [a, b] = [b, a + b]; return a } }
@Module({ controllers: [C] }) class AppModule {}

async function main() {
    const ms = await NestFactory.createMicroservice<MicroserviceOptions>(AppModule, { transport: Transport.TCP, options: { host: "127.0.0.1", port: 4849 }, logger: false })
    await ms.listen()
    const c = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4849 } })
    for (const n of [30, 30, 40, 30]) await firstValueFrom(c.send("fib", n))
    console.log("fib(30) =", await firstValueFrom(c.send("fib", 30)), "| haqiqiy hisoblashlar:", computed)
    await c.close(); await ms.close()
}
main()

