@Controller() class Users { @MessagePattern("users.find") f(_: unknown) {} @MessagePattern({ cmd: "users.count" }) c(_: unknown) {} @EventPattern("user.registered") r(_: unknown) {} }
const proto = Users.prototype as unknown as Record<string, Function>
for (const name of Object.getOwnPropertyNames(proto).filter(n => n !== "constructor")) {
    const patterns = Reflect.getMetadata("microservices:pattern", proto[name]) as unknown[]
    const kind = Reflect.getMetadata("microservices:handler_type", proto[name]) === 2 ? "event" : "message"
    console.log(`${name}() → ${kind}: ${JSON.stringify(patterns)}`)
}

