import { BaseRpcExceptionFilter, ClientProxyFactory, MessagePattern, MicroserviceOptions, Payload, RpcException, Transport } from "@nestjs/microservices"
import { firstValueFrom } from "rxjs"
import { z } from "zod"

const SumSchema = z.object({ a: z.number(), b: z.number() })

@Catch(BadRequestException)
class SchemaErrorFilter extends BaseRpcExceptionFilter {
    catch(e: BadRequestException, host: ArgumentsHost) {
        return super.catch(new RpcException(e.getResponse()), host)   // mijozga tafsilot bilan boradi
    }
}

