    async send(email: string) {
        if (!email.includes("@")) throw new Error("manzil noto'g'ri")
        console.log("xat yuborildi:", email)
    }
}

@Controller()
class InvoicesController {
    constructor(private readonly mailer: Mailer) {}

    @EventPattern("invoice.send")
    async send(@Payload() invoice: { email: string }, @Ctx() context: RmqContext) {
        const channel = context.getChannelRef()
        const message = context.getMessage()
        try {
            await this.mailer.send(invoice.email)
            channel.ack(message)                           // muvaffaqiyat: navbatdan o'chadi
        } catch (error) {
            console.log("rad etildi:", (error as Error).message)
            channel.nack(message, false, false)            // xato: qayta navbatga qo'yilmaydi
        }
    }
}

