@Controller() class UsersMs { @MessagePattern("user.get") get() { return { id: 1, name: "Ali" } } }
@Module({ controllers: [UsersMs] }) class UsersMsModule {}
@Controller() class OrdersMs { @MessagePattern("orders.byUser") by() { return [{ id: 11, total: 90000 }, { id: 12, total: 45000 }] } }
@Module({ controllers: [OrdersMs] }) class OrdersMsModule {}

@Controller("profile")
class ApiController {
    constructor(@Inject("USERS") private readonly users: ClientProxy, @Inject("ORDERS") private readonly orders: ClientProxy) {}
    @Get() async profile() {
        const [user, orders] = await Promise.all([
            firstValueFrom(this.users.send("user.get", 1)),
            firstValueFrom(this.orders.send<{ total: number }[]>("orders.byUser", 1)),
        ])
        return { ...user, orders: orders.length, spent: orders.reduce((s, o) => s + o.total, 0) }
    }
}
@Module({
    imports: [ClientsModule.register([
        { name: "USERS", transport: Transport.TCP, options: { host: "127.0.0.1", port: 4533 } },
        { name: "ORDERS", transport: Transport.TCP, options: { host: "127.0.0.1", port: 4534 } },
    ])],
    controllers: [ApiController],
})
class ApiModule {}

async function main() {
    const opts = (port: number) => ({ transport: Transport.TCP as const, options: { host: "127.0.0.1", port }, logger: false as const })
    const users = await NestFactory.createMicroservice<MicroserviceOptions>(UsersMsModule, opts(4533))
    const orders = await NestFactory.createMicroservice<MicroserviceOptions>(OrdersMsModule, opts(4534))
    await users.listen(); await orders.listen()
    const http = await testApp(ApiModule)
    await http.get("/profile")
    await http.close()
    await users.close(); await orders.close()
}
main()

