import { Controller, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxyFactory, MessagePattern, MicroserviceOptions, RpcException, Transport } from "@nestjs/microservices"
import { firstValueFrom, retry } from "rxjs"

@Controller()
class FlakyMs {
    private calls = 0
    @MessagePattern("data") data() {
        this.calls++
        if (this.calls < 3) throw new RpcException(`vaqtinchalik xato (${this.calls})`)
        return { ok: true, attempts: this.calls }
    }
}
@Module({ controllers: [FlakyMs] }) class FlakyModule {}

async function main() {
    const ms = await NestFactory.createMicroservice<MicroserviceOptions>(FlakyModule, { transport: Transport.TCP, options: { host: "127.0.0.1", port: 4626 }, logger: false })
    await ms.listen()
    const client = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4626 } })
    console.log(await firstValueFrom(client.send("data", {}).pipe(retry({ count: 3, delay: 20 }))))
    await client.close(); await ms.close()
}
main()

