import { Controller, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxy, ClientProxyFactory, ClientsModule, MessagePattern, MicroserviceOptions, Transport } from "@nestjs/microservices"
import type { Server } from "node:net"
import { firstValueFrom } from "rxjs"

@Controller()
class PingController {
    @MessagePattern("ping")
    ping() { return "pong" }
}

@Module({ controllers: [PingController] })
class PingModule {}

const options = { host: "127.0.0.1", port: 4944 }

@Injectable()
class ManualClient {
    readonly client = ClientProxyFactory.create({ transport: Transport.TCP, options })   // qo'lda yaratilgan
}

@Module({
    imports: [ClientsModule.register([{ name: "AUTO", transport: Transport.TCP, options }])],   // modul boshqaradi
    providers: [ManualClient],
})
class AppModule {}

const connections = (server: Server) => new Promise<number>(resolve => server.getConnections((_, n) => resolve(n)))
const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms))

async function main() {
    const ms = await NestFactory.createMicroservice<MicroserviceOptions>(PingModule, { transport: Transport.TCP, options, logger: false })
    await ms.listen()
    const server = ms.unwrap<Server>()

    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const manual = app.get(ManualClient).client
    await firstValueFrom(app.get<ClientProxy>("AUTO").send("ping", {}))
    await firstValueFrom(manual.send("ping", {}))
    console.log("ilova ishlayotganda ulanishlar:", await connections(server))

    await app.close()
    await wait(100)
    console.log("app.close() dan keyin:", await connections(server), "(ClientProxyFactory mijozi qoldi)")

    await manual.close()
    await wait(100)
    console.log("manual.close() dan keyin:", await connections(server))
    await ms.close()
}
main()

