import { Controller, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxy, ClientProxyFactory, MessagePattern, MicroserviceOptions, Transport } from "@nestjs/microservices"
import { firstValueFrom } from "rxjs"

@Controller() class RegionMs { @MessagePattern("region") r() { return "javob keldi" } }
@Module({ controllers: [RegionMs] }) class RegionModule {}

@Injectable()
class RegionRouter {
    private clients = new Map<string, ClientProxy>()
    client(region: string, port: number) {
        if (!this.clients.has(region)) this.clients.set(region, ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port } }))
        return this.clients.get(region)!
    }
    async closeAll() { for (const c of this.clients.values()) await c.close() }
}
@Module({ providers: [RegionRouter] }) class AppModule {}

async function main() {
    const ms = await NestFactory.createMicroservice<MicroserviceOptions>(RegionModule, { transport: Transport.TCP, options: { host: "127.0.0.1", port: 4631 }, logger: false })
    await ms.listen()
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const router = app.get(RegionRouter)
    console.log("tashkent:", await firstValueFrom(router.client("tashkent", 4631).send("region", {})))
    console.log("bir xil mijoz qayta ishlatildi:", router.client("tashkent", 4631) === router.client("tashkent", 4631))
    await router.closeAll(); await app.close(); await ms.close()
}
main()

