let serverCalls = 0
@Controller() class Rates { @MessagePattern("rate") rate(cur: string) { serverCalls++; return cur === "USD" ? 12650 : 13700 } }
@Module({ controllers: [Rates] }) class AppModule {}

class CachedClient {
    private readonly cache = new Map<string, { value: unknown; until: number }>()
    constructor(private readonly client: ClientProxy, private readonly ttlMs: number) {}

    async send<T>(pattern: string, data: unknown): Promise<T> {
        const key = `${pattern}:${JSON.stringify(data)}`
        const hit = this.cache.get(key)
        if (hit && hit.until > Date.now()) return hit.value as T
        const value = await firstValueFrom(this.client.send<T>(pattern, data))
        this.cache.set(key, { value, until: Date.now() + this.ttlMs })
        return value
    }
}

