class RoundRobin {
    private next = 0
    constructor(private readonly clients: ClientProxy[]) {}
    send<T>(pattern: string, data: unknown) {
        const client = this.clients[this.next++ % this.clients.length]
        return firstValueFrom(client.send<T>(pattern, data))
    }
}

async function main() {
    const servers = []
    for (const [name, port] of [["nusxa-A", 4866], ["nusxa-B", 4867]] as const) {
