    const clients = [4866, 4867].map(port => ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port } }))
    const rr = new RoundRobin(clients)
    for (let i = 1; i <= 4; i++) console.log(`${i}-so'rov →`, await rr.send("who", {}))
    for (const c of clients) await c.close()
    for (const s of servers) await s.close()
}
