    @MessagePattern("stock") stock(_: string) { return 12 }
}
@Module({ controllers: [Shop] }) class AppModule {}

class MeteredClient {
    readonly stats = new Map<string, { ok: number; fail: number }>()
    constructor(private readonly client: ClientProxy) {}

    async send<T>(pattern: string, data: unknown): Promise<T | undefined> {
        const s = this.stats.get(pattern) ?? { ok: 0, fail: 0 }
        this.stats.set(pattern, s)
        try {
            const result = await firstValueFrom(this.client.send<T>(pattern, data))
            s.ok++
            return result
        } catch {
            s.fail++
            return undefined
        }
    }
}

async function main() {
    const ms = await NestFactory.createMicroservice<MicroserviceOptions>(AppModule, { transport: Transport.TCP, options: { host: "127.0.0.1", port: 4879 }, logger: false })
    await ms.listen()
    const c = new MeteredClient(ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4879 } }))
    for (const item of ["non", "choy", "?"]) await c.send("price", item)
    await c.send("stock", "non")
    console.table(Object.fromEntries(c.stats))
    await ms.close()
}
