import { firstValueFrom, timeout, TimeoutError } from "rxjs"

@Controller()
class Svc {
    @MessagePattern("a") a(_: unknown) { throw new RpcException({ code: "NOT_FOUND", message: "Buyurtma yo'q" }) }
    @MessagePattern("b") b(_: unknown) { throw new RpcException("Oddiy matnli xato") }
    @MessagePattern("c") async c(_: unknown) { await new Promise(r => setTimeout(r, 200)); return 1 }
}
@Module({ controllers: [Svc] }) class AppModule {}

function normalize(e: unknown): { code: string; message: string } {
    if (e instanceof TimeoutError) return { code: "TIMEOUT", message: "Servis javob bermadi" }
    const x = e as { code?: string; message?: string }
    if (x.code === "ECONNREFUSED") return { code: "UNAVAILABLE", message: "Servis o'chiq" }
    if (x.code) return { code: x.code, message: x.message ?? "" }
    return { code: "INTERNAL", message: x.message ?? "Noma'lum xato" }
}

async function main() {
    const ms = await NestFactory.createMicroservice<MicroserviceOptions>(AppModule, { transport: Transport.TCP, options: { host: "127.0.0.1", port: 4881 }, logger: false })
    await ms.listen()
    const live = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4881 } })
    const dead = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4882 } })
    const cases: [string, ClientProxy, string][] = [["a", live, "a"], ["b", live, "b"], ["c", live, "c"], ["o'chiq", dead, "a"]]
    for (const [label, client, pattern] of cases) {
        try { await firstValueFrom(client.send(pattern, {}).pipe(timeout(100))) }
        catch (e) { console.log(label.padEnd(7), "→", normalize(e)) }
    }
    await live.close(); await dead.close(); await ms.close()
}
