import { Controller, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxyFactory, MessagePattern, MicroserviceOptions, RpcException, Transport } from "@nestjs/microservices"
import { firstValueFrom, Observable, retry, throwError, timer } from "rxjs"

let attempts = 0
@Controller()
class Payments {
    @MessagePattern("pay") pay(d: { amount: number }) {
        attempts++
        if (d.amount <= 0) throw new RpcException({ code: "INVALID_AMOUNT", retryable: false })
        if (attempts < 3) throw new RpcException({ code: "BUSY", retryable: true })
        return { paid: d.amount }
    }
}
@Module({ controllers: [Payments] }) class AppModule {}

const withRetry = <T>(source: Observable<T>) =>
    source.pipe(retry({ count: 3, delay: (e: { retryable?: boolean }) => (e.retryable ? timer(10) : throwError(() => e)) }))

async function main() {
    const ms = await NestFactory.createMicroservice<MicroserviceOptions>(AppModule, { transport: Transport.TCP, options: { host: "127.0.0.1", port: 4890 }, logger: false })
    await ms.listen()
    const c = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4890 } })
    console.log(await firstValueFrom(withRetry(c.send("pay", { amount: 5000 }))), "| urinishlar:", attempts)
    attempts = 0
    try { await firstValueFrom(withRetry(c.send("pay", { amount: 0 }))) }
    catch (e) { console.log("xato:", e, "| urinishlar:", attempts) }
    await c.close(); await ms.close()
}
main()

import { Controller, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxyFactory, MessagePattern, MicroserviceOptions, RpcException, Transport } from "@nestjs/microservices"
import { firstValueFrom } from "rxjs"

let down = true, serverCalls = 0
@Controller() class Stock { @MessagePattern("stock") stock(_: unknown) { serverCalls++; if (down) throw new RpcException("ombor ishlamayapti"); return 12 } }
@Module({ controllers: [Stock] }) class AppModule {}

class Breaker {
    private fails = 0
    private openUntil = 0
    constructor(private readonly limit: number, private readonly coolMs: number) {}

    async call<T>(fn: () => Promise<T>): Promise<T> {
        if (Date.now() < this.openUntil) throw new Error("OCHIQ — so'rov yuborilmadi")
        try {
            const r = await fn()
            this.fails = 0
            return r
        } catch (e) {
            if (++this.fails >= this.limit) this.openUntil = Date.now() + this.coolMs
            throw e
        }
    }
}

async function main() {
    const ms = await NestFactory.createMicroservice<MicroserviceOptions>(AppModule, { transport: Transport.TCP, options: { host: "127.0.0.1", port: 4891 }, logger: false })
    await ms.listen()
    const c = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4891 } })
    const breaker = new Breaker(3, 100)
    const ask = () => breaker.call(() => firstValueFrom(c.send<number>("stock", "non")))
    for (let i = 1; i <= 5; i++) {
        try { await ask() } catch (e) { console.log(`${i}:`, (e as { message: string }).message) }
    }
    down = false
    await new Promise(r => setTimeout(r, 120))
    console.log("sovugandan keyin:", await ask(), "| serverga yetgan so'rovlar:", serverCalls)
    await c.close(); await ms.close()
}
main()

