import { Controller, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClientProxyFactory, MessagePattern, MicroserviceOptions, Transport } from "@nestjs/microservices"
import { firstValueFrom } from "rxjs"

let active = 0, peak = 0
@Controller() class Pdf { @MessagePattern("pdf") async pdf(n: number) { active++; peak = Math.max(peak, active); await new Promise(r => setTimeout(r, 30)); active--; return `chek-${n}.pdf` } }
@Module({ controllers: [Pdf] }) class AppModule {}

function limiter(max: number) {
    let running = 0
    const queue: (() => void)[] = []
    return async <T>(task: () => Promise<T>): Promise<T> => {
        if (running >= max) await new Promise<void>(r => queue.push(r))
        running++
        try { return await task() }
        finally { running--; queue.shift()?.() }
    }
}

async function main() {
    const ms = await NestFactory.createMicroservice<MicroserviceOptions>(AppModule, { transport: Transport.TCP, options: { host: "127.0.0.1", port: 4893 }, logger: false })
    await ms.listen()
    const c = ClientProxyFactory.create({ transport: Transport.TCP, options: { host: "127.0.0.1", port: 4893 } })
    const limit = limiter(2)
    const files = await Promise.all([1, 2, 3, 4, 5, 6].map(n => limit(() => firstValueFrom(c.send<string>("pdf", n)))))
    console.log(files, "| serverda bir vaqtdagi eng ko'p:", peak)
    await c.close(); await ms.close()
}
main()

