class AuditController {
    @EventPattern("user.logged_in")
    onLogin(@Payload() event: { userId: number }, @Ctx() context: KafkaContext) {
        const message = context.getMessage()               // asl Kafka xabari: key, headers, offset...
        console.log(`key=${message.key} trace=${message.headers["x-trace"]} userId=${event.userId}`)
    }
}

@Module({ controllers: [AuditController] })
class AuditModule {}

const kafka = { client: { clientId: "audit", brokers: ["localhost:9092"] }, consumer: { groupId: "audit-keys" } }

async function main() {
    const app = await NestFactory.createMicroservice<MicroserviceOptions>(AuditModule, { transport: Transport.KAFKA, options: kafka, logger: false })
    await app.listen()

    const client = ClientProxyFactory.create({ transport: Transport.KAFKA, options: kafka })
    await client.connect()
    await firstValueFrom(client.emit("user.logged_in", {
        key: "user-42",                                    // partition tanlash uchun
        value: { userId: 42 },                             // @Payload() shuni oladi
        headers: { "x-trace": "tr-1" },
    }))
    await new Promise(resolve => setTimeout(resolve, 500))
    await client.close()
    await app.close()
}
main()
